ALTER TABLE users ADD COLUMN email TEXT;
CREATE UNIQUE INDEX idx_users_email ON users(email);
ALTER TABLE users ADD COLUMN credential_scheme TEXT NOT NULL DEFAULT 'raw-bcrypt';
ALTER TABLE events ADD COLUMN subtitle TEXT NOT NULL DEFAULT '';
ALTER TABLE events ADD COLUMN event_type TEXT NOT NULL DEFAULT 'trip';
ALTER TABLE events ADD COLUMN start_at TEXT;
ALTER TABLE events ADD COLUMN end_at TEXT;
ALTER TABLE events ADD COLUMN revision INTEGER NOT NULL DEFAULT 1;
ALTER TABLE participants ADD COLUMN user_id TEXT REFERENCES users(id);
CREATE UNIQUE INDEX idx_participants_user ON participants(event_id,user_id);
ALTER TABLE photos ADD COLUMN uploader_id TEXT REFERENCES users(id);
UPDATE photos SET uploader_id=(SELECT owner_id FROM events WHERE events.id=photos.event_id);
CREATE TABLE event_members(event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),participant_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','member')),PRIMARY KEY(event_id,user_id),FOREIGN KEY(event_id,participant_id) REFERENCES participants(event_id,id));
INSERT INTO participants(id,event_id,name,initials,color,user_id) SELECT 'owner:'||e.id,e.id,u.username,substr(u.username,1,2),'#c77455',u.id FROM events e JOIN users u ON u.id=e.owner_id;
INSERT INTO event_members SELECT id,owner_id,'owner:'||id,'owner' FROM events;
CREATE TABLE memory_scenes(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,content TEXT NOT NULL,UNIQUE(event_id,id));
CREATE TABLE memory_moments(id TEXT PRIMARY KEY,event_id TEXT NOT NULL,scene_id TEXT NOT NULL,origin_gap_id TEXT,content TEXT NOT NULL,UNIQUE(event_id,id),UNIQUE(event_id,origin_gap_id),FOREIGN KEY(event_id,scene_id) REFERENCES memory_scenes(event_id,id) ON DELETE CASCADE);
CREATE TABLE contributions(id TEXT PRIMARY KEY,event_id TEXT NOT NULL,moment_id TEXT NOT NULL,participant_id TEXT NOT NULL,owner_user_id TEXT NOT NULL REFERENCES users(id),version INTEGER NOT NULL CHECK(version>0),visibility TEXT NOT NULL CHECK(visibility IN ('private','event-members','public')),photo_id TEXT REFERENCES photos(id),thumbnail_photo_id TEXT REFERENCES photos(id),background_photo_id TEXT REFERENCES photos(id),content TEXT NOT NULL,request_json TEXT NOT NULL,UNIQUE(event_id,id),FOREIGN KEY(event_id,moment_id) REFERENCES memory_moments(event_id,id) ON DELETE CASCADE,FOREIGN KEY(event_id,participant_id) REFERENCES participants(event_id,id));
CREATE INDEX idx_contributions_event ON contributions(event_id,moment_id);
CREATE TABLE memory_links(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,content TEXT NOT NULL);
CREATE TABLE memory_link_moments(link_id TEXT NOT NULL REFERENCES memory_links(id) ON DELETE CASCADE,moment_id TEXT NOT NULL REFERENCES memory_moments(id) ON DELETE CASCADE,PRIMARY KEY(link_id,moment_id));
CREATE TABLE memory_link_contributions(link_id TEXT NOT NULL REFERENCES memory_links(id) ON DELETE CASCADE,contribution_id TEXT NOT NULL REFERENCES contributions(id) ON DELETE CASCADE,PRIMARY KEY(link_id,contribution_id));
CREATE TABLE memory_pairs(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,scene_id TEXT NOT NULL REFERENCES memory_scenes(id),before_id TEXT NOT NULL REFERENCES contributions(id) ON DELETE CASCADE,after_id TEXT NOT NULL REFERENCES contributions(id) ON DELETE CASCADE,content TEXT NOT NULL);
CREATE TABLE discovery_feedback(event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),finding_id TEXT NOT NULL,content TEXT NOT NULL,evidence_json TEXT NOT NULL,PRIMARY KEY(event_id,user_id,finding_id));
CREATE TABLE consent_audit(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),contribution_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),visibility TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE memory_requests(user_id TEXT NOT NULL REFERENCES users(id),request_id TEXT NOT NULL,request_json TEXT NOT NULL,response_json TEXT NOT NULL,PRIMARY KEY(user_id,request_id));
INSERT INTO memory_scenes SELECT 'scene:'||id,id,json_object('id','scene:'||id,'eventId',id,'title',name,'subtitle','','environment',json_object('preset','neutral')) FROM events;
INSERT INTO memory_moments SELECT 'moment:'||id,id,'scene:'||id,NULL,json_object('id','moment:'||id,'sceneId','scene:'||id,'title','First chapter','startAt',strftime('%Y-%m-%dT%H:%M:%SZ',created_at/1000,'unixepoch'),'label','Today','lighting','morning') FROM events;
INSERT INTO contributions SELECT 'photo:'||p.id,p.event_id,'moment:'||p.event_id,p.photographer_id,e.owner_id,1,'event-members',p.id,NULL,NULL,json_object('id','photo:'||p.id,'momentId','moment:'||p.event_id,'participantId',p.photographer_id,'kind','photo','writtenText',p.caption,'mood',json('[]'),'isDemo',json('false'),'alt',p.filename,'photoId',p.id,'capturedAt',p.captured_at), '{}' FROM photos p JOIN events e ON e.id=p.event_id WHERE p.status='READY';
